js='''const cards=[...document.querySelectorAll('[data-code]')];function filter(){const q=document.querySelector('#productSearch').value.trim().toLowerCase(),d=document.querySelector('#department').value;let n=0;for(const c of cards){c.hidden=!c.dataset.search.toLowerCase().includes(q)||(d!=='All'&&c.dataset.dept!==d);if(!c.hidden)n++;}document.querySelector('#shown').textContent=n+' of 150 product homes';}document.querySelector('#productSearch').oninput=filter;document.querySelector('#department').onchange=filter;function update(){for(const c of cards){const p=window.HFInventory.forCode(c.dataset.code);c.querySelector('[data-hand]').textContent=window.HFInventory.format(p?.onHand);c.querySelector('[data-committed]').textContent=window.HFInventory.format(p?.committed);const note=c.querySelector('[data-report]');note.classList.toggle('attention',p?.onHand<0);note.textContent='Whole warehouse · Read only · '+(p?.onHand<0?'Count needs checking · ':p?.status==='stale'?'Saved report ':p?.onHand==null?'Count unavailable ': 'Updated ')+(p?.reportedAt?window.HFInventory.when(p.reportedAt):'');}}document.addEventListener('hf:inventory',update);window.HFInventory.ready.then(update);'''
